{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "A comparative study reported the oral bioavailability of pyridostigmine, the query molecule, as 7.6%, which is well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Neostigmine, a close structural analogue sharing the quaternary ammonium dimethylcarbamate motif, had an absolute oral bioavailability of only 2.0 ± 0.33% in fasted patients, indicating very poor systemic exposure for this charged carbamate class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Bambuterol, a non-quaternary dimethylcarbamate prodrug, has only about 10% oral bioavailability, showing that even without a permanent charge these carbamates undergo extensive presystemic loss; the query's permanent positive charge would further impair absorption.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is pyridostigmine, a permanently charged quaternary ammonium carbamate. Direct comparative data give pyridostigmine an oral bioavailability of about 7.6%, and the very close analogue neostigmine shows only 1-2% absolute oral bioavailability. These experimental results outweigh the uncertain physicochemical prior and clearly support F < 20%.",
  "evidence_gaps": [
    "No dedicated dose-ranging absolute bioavailability study for pyridostigmine is included; C46 is a comparative mention.",
    "Salt form and counterion are not specified, which could influence solubility and absorption.",
    "Potential contributions of active transport or paracellular absorption are not quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

